// Some portions generated by Co-Pilot
import React from "react";
import { fireEvent, render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { axe } from "vitest-axe";
import Sustainers from "../page";

describe("Sustainers page", () => {
  it("renders correctly", () => {
    const { container } = render(<Sustainers />);
    expect(container.firstChild).toMatchSnapshot();
  });

  it("has no accessibility violations", async () => {
    const { container } = render(<Sustainers />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("preserves both ways to support the project without nested buttons", () => {
    const { container } = render(<Sustainers />);
    expect(screen.getAllByRole("heading", { level: 1 })).toHaveLength(1);
    for (const link of screen.getAllByRole("link", {
      name: "Become an Individual Sustainer",
    })) {
      expect(link).toHaveAttribute(
        "href",
        "https://www.eclipse.org/sponsor/adoptium/?scope=website&campaign=become-sustainer",
      );
      expect(link).toHaveAttribute("target", "_blank");
      expect(link).toHaveAttribute("rel", "noopener noreferrer");
    }
    for (const link of screen.getAllByRole("link", {
      name: "Become a Corporate Sustainer",
    })) {
      expect(link).toHaveAttribute("href", "/become-a-sustainer");
    }
    expect(container.querySelector("a button")).not.toBeInTheDocument();
  });

  it("keeps all five tier amounts and their full benefits available", () => {
    const { container } = render(<Sustainers />);
    const tiers = [
      { title: "Diamond", amount: "€100k/year", count: 9 },
      { title: "Platinum", amount: "€75k/year", count: 7 },
      { title: "Gold", amount: "€50k/year", count: 6 },
      { title: "Silver", amount: "€30k/year", count: 5 },
      { title: "Bronze", amount: "€10k/year", count: 4 },
    ];
    for (const tier of tiers) {
      const heading = screen.getByRole("heading", {
        level: 3,
        name: tier.title,
      });
      const card = heading.closest("details")!;
      expect(screen.getByText(tier.amount)).toBeVisible();
      expect(card.querySelectorAll("li")).toHaveLength(tier.count);
      fireEvent.click(card.querySelector("summary")!);
      expect(
        screen.getByRole("heading", {
          level: 4,
          name: `${tier.title} Benefits`,
        }),
      ).toBeVisible();
    }
    expect(
      container.querySelector(".open-animation-wrapper"),
    ).not.toBeInTheDocument();
  });

  it("keeps the existing savings calculator integration and study qualifier", () => {
    const { container, unmount } = render(<Sustainers />);
    expect(container.querySelector(".involveme_embed")).toHaveAttribute(
      "data-project",
      "temurin-calculator",
    );
    expect(
      document.querySelectorAll(
        'script[src="https://eclipse-foundation.involve.me/embed"]',
      ),
    ).toHaveLength(1);
    expect(
      screen.getByText("*Self-reported number of employees, n = 211"),
    ).toBeVisible();
    unmount();
    expect(
      document.querySelector(
        'script[src="https://eclipse-foundation.involve.me/embed"]',
      ),
    ).not.toBeInTheDocument();
  });

  it("preserves sustainer logos and does not render empty section headings", () => {
    const { container } = render(<Sustainers />);
    expect(container.querySelector("#temurin-sustainers")).toBeInTheDocument();
    expect(screen.getByRole("link", { name: "CarGurus" })).toHaveAttribute(
      "href",
      "https://www.cargurus.com",
    );
    expect(
      screen.getByRole("link", { name: "Microsoft Azure" }),
    ).toHaveAttribute("href", "https://azure.microsoft.com");
    for (const heading of screen.getAllByRole("heading"))
      expect(heading.textContent?.trim().length).toBeGreaterThan(0);
  });
});
